  if (tradeCount < 10) {
    return {
      label: "Small sample",
      level: "low",
      summary: "Enough to preview the workflow, not enough to judge the account with confidence.",
      caveats: [`Only ${tradeCount} trade${tradeCount === 1 ? "" : "s"} reviewed.`, ...caveats],
    };
  }

  if (tradeCount < 25) {
    return {
      label: "Building sample",
      level: "medium",
